const aliases = new Map([
  ['T-shirt','T-shirt'],['English','English'],['Monday','Monday'],['Tuesday','Tuesday'],
  ['Wednesday','Wednesday'],['Thursday','Thursday'],['Friday','Friday'],['Saturday','Saturday'],
  ['Sunday','Sunday'],['January','January'],['February','February'],['March','March'],
  ['April','April'],['May','May'],['June','June'],['July','July'],['August','August'],
  ['September','September'],['October','October'],['November','November'],['December','December']
]);

export const vocabularyBank = [];
const seen = new Set();
for (const [topic, source] of Object.entries(groups)) {
  for (const entry of source.split(';')) {
    const [rawWord, zh] = entry.split('=');
    const word = aliases.get(rawWord) || rawWord;
    const key = word.toLowerCase();
    if (!word || !zh || seen.has(key)) continue;
    seen.add(key);
    vocabularyBank.push({word, zh, topic, pos: word.includes(' ') ? 'A2 phrase' : 'A2 word'});
  }
}

